CREATE TABLE IF NOT EXISTS practice_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE practitioners(id uuid PRIMARY KEY, issuer text NOT NULL, subject text NOT NULL, display_name text NOT NULL, UNIQUE(issuer,subject));
CREATE TABLE memberships(organization_id uuid NOT NULL REFERENCES organizations(id), practitioner_id uuid NOT NULL REFERENCES practitioners(id), role text NOT NULL CHECK(role IN ('clinician','reviewer','admin')), active boolean NOT NULL DEFAULT true, PRIMARY KEY(organization_id,practitioner_id));
CREATE TABLE practice_sessions(token_hash text PRIMARY KEY, practitioner_id uuid NOT NULL REFERENCES practitioners(id), organization_id uuid NOT NULL REFERENCES organizations(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oidc_flows(state_hash text PRIMARY KEY, verifier text NOT NULL, nonce text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE practice_patients(id uuid NOT NULL, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, dob date NOT NULL, identifier text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id), UNIQUE(organization_id,identifier));
CREATE TABLE care_relationships(organization_id uuid NOT NULL, patient_id uuid NOT NULL, practitioner_id uuid NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(organization_id,patient_id,practitioner_id), FOREIGN KEY(organization_id,patient_id) REFERENCES practice_patients(organization_id,id), FOREIGN KEY(organization_id,practitioner_id) REFERENCES memberships(organization_id,practitioner_id));
CREATE TABLE practice_documents(id uuid NOT NULL, organization_id uuid NOT NULL, patient_id uuid NOT NULL, uploaded_by uuid NOT NULL REFERENCES practitioners(id), filename text NOT NULL, mime_type text NOT NULL, byte_size integer NOT NULL CHECK(byte_size>0), checksum text NOT NULL, original_bytes bytea NOT NULL, version integer NOT NULL DEFAULT 1, status text NOT NULL CHECK(status IN ('quarantined','available','rejected')), extracted_text text, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id), FOREIGN KEY(organization_id,patient_id) REFERENCES practice_patients(organization_id,id));
CREATE TABLE practice_notes(id uuid NOT NULL, organization_id uuid NOT NULL, patient_id uuid NOT NULL, author_id uuid NOT NULL REFERENCES practitioners(id), content text NOT NULL, amends_id uuid, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')), approved_by uuid REFERENCES practitioners(id), approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id), FOREIGN KEY(organization_id,patient_id) REFERENCES practice_patients(organization_id,id));
CREATE TABLE practice_note_versions(id uuid PRIMARY KEY, organization_id uuid NOT NULL, note_id uuid NOT NULL, version integer NOT NULL, content text NOT NULL, author_id uuid NOT NULL REFERENCES practitioners(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,note_id,version), FOREIGN KEY(organization_id,note_id) REFERENCES practice_notes(organization_id,id));
CREATE TABLE practice_medications(id uuid NOT NULL, organization_id uuid NOT NULL, patient_id uuid NOT NULL, name text NOT NULL, dose text NOT NULL, route text NOT NULL, frequency text NOT NULL, status text NOT NULL CHECK(status IN ('reported','verified','stopped')), source text NOT NULL, recorded_by uuid NOT NULL REFERENCES practitioners(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id), FOREIGN KEY(organization_id,patient_id) REFERENCES practice_patients(organization_id,id));
CREATE TABLE practice_summaries(id uuid NOT NULL, organization_id uuid NOT NULL, patient_id uuid NOT NULL, note jsonb NOT NULL, sources jsonb NOT NULL, model text NOT NULL, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')), created_by uuid NOT NULL REFERENCES practitioners(id), approved_by uuid REFERENCES practitioners(id), approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id), FOREIGN KEY(organization_id,patient_id) REFERENCES practice_patients(organization_id,id));
CREATE TABLE practice_audit(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), practitioner_id uuid REFERENCES practitioners(id), action text NOT NULL, resource_id text, outcome text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX practice_audit_tenant ON practice_audit(organization_id,created_at);
CREATE INDEX practice_patient_care ON care_relationships(organization_id,practitioner_id,active);
CREATE INDEX practice_session_expiry ON practice_sessions(expires_at);
INSERT INTO practice_migrations(version) VALUES(1);

ALTER TABLE practice_notes ADD CONSTRAINT practice_note_amends_fk FOREIGN KEY(organization_id,amends_id) REFERENCES practice_notes(organization_id,id);
CREATE TABLE practice_request_limits(key text PRIMARY KEY, count integer NOT NULL, reset_at timestamptz NOT NULL);
